 "content": "from collections import deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and p not in seen
                            and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            min_r = min(y for y, x in cells)
            min_c = min(x for y, x in cells)
            shape = frozenset((y - min_r, x - min_c) for y, x in cells)
            yield color, cells, shape


def transform(grid):
    out = [row[:] for row in grid]
    comps = list(_components(grid))
    colors_by_shape = {}
    for color, cells, shape in comps:
        if color != 1:
            colors_by_shape.setdefault(shape, set()).add(color)
    for color, cells, shape in comps:
        if color == 1 and shape in colors_by_shape and len(colors_by_shape[shape]) == 1:
            replacement = next(iter(colors_by_shape[shape]))
            for r, c in cells:
                out[r][c] = replacement
    return out
